{
  "components": [
    {
      "type": "claim",
      "quote": "The president is 'primus inter pares' – first among equals.",
      "gist": "The Swiss Confederation president is considered first among equals."
    },
    {
      "type": "obligation",
      "quote": "He or she chairs the Federal Council meetings and mediates in the case of disputes.",
      "gist": "The president must chair Federal Council meetings and mediate disputes."
    },
    {
      "type": "obligation",
      "quote": "In urgent situations the president can order precautionary measures.",
      "gist": "The president is authorized to order precautionary measures in urgent situations."
    },
    {
      "type": "obligation",
      "quote": "In the unlikely event that the Federal Council is unable to hold either an ordinary or an extraordinary meeting, the president may take a unilateral decision.",
      "gist": "The president may make a unilateral decision if the Federal Council cannot meet."
    },
    {
      "type": "entity",
      "quote": "the vice president of the Federal Council",
      "gist": "Vice president of the Swiss Federal Council"
    }
  ]
}
